/**
 * Natural-language → Room Management suggestions (2026-07-27 — "add like an
 * ai feature so either i can type it out and it will update the delegate
 * room status, but give user the confirmation before update the changes").
 *
 * BOUNDED + TRANSPARENT by design, same pattern as export.js's ai-filter and
 * insights.js's AI Insights: the model only ever picks delegateIds that
 * ACTUALLY exist on this trip's roomable roster (coach-assigned delegates,
 * same scope Room Management's own UI already uses) and only ever proposes
 * a hotelName/roomNumber pair — never anything else, never applied directly.
 *
 * Two-step, both requiring manageDelegates:
 *   POST /api/trips/:id/rooms/ai-suggest → { suggestions: [{delegateId, name, hotelName, roomNumber}] }
 *     Read-only — writes NOTHING. The frontend merges these into its
 *     existing per-row "pending edit" state (the same dirty-row/Save
 *     affordance manual edits already use), so nothing is written until a
 *     human explicitly clicks Save on a row (or "Save all suggested").
 *   POST /api/trips/:id/rooms/ai-apply → re-validates every {delegateId,
 *     hotelName, roomNumber} against the SAME roomable roster server-side
 *     (never trusts the client's suggestion list blindly) before writing —
 *     this is the actual write path, only ever called after that explicit
 *     confirm click.
 *
 * Provider strategy mirrors export.js/insights.js exactly: local Ollama
 * first (free, nothing leaves the machine), Anthropic API fallback, a clear
 * 503 if neither is configured — never crashes, never silently no-ops.
 */
import { Router } from "express";
import { wrap } from "../lib/wrap.js";
import { requirePermission } from "../lib/auth.js";
import { actorOf } from "../lib/actor.js";
import { resolveTripUuid, listDelegates, updateDelegate, getVisibleCoachIds } from "../data.js";

const router = Router();

const MAX_SUGGESTIONS = 100; // sane upper bound — a real roster's worth, not unbounded model output

async function tryOllama(prompt, { numPredict } = {}) {
  const base = process.env.OLLAMA_HOST || "http://localhost:11434";
  const model = process.env.OLLAMA_MODEL || "llama3.2";
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 30000);
  try {
    const res = await fetch(`${base}/api/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model, messages: [{ role: "user", content: prompt }], stream: false,
        keep_alive: "30m", format: "json",
        ...(numPredict ? { options: { num_predict: numPredict } } : {}),
      }),
      signal: controller.signal,
    });
    if (!res.ok) return null;
    const data = await res.json();
    return data?.message?.content?.trim() || null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

async function callAnthropic(prompt, maxTokens = 800) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return null;
  const { default: Anthropic } = await import("@anthropic-ai/sdk");
  const anthropic = new Anthropic({ apiKey });
  const model = process.env.ANTHROPIC_MODEL || "claude-sonnet-4-5-20250929";
  const response = await anthropic.messages.create({ model, max_tokens: maxTokens, messages: [{ role: "user", content: prompt }] });
  return (response.content || []).filter((b) => b.type === "text").map((b) => b.text).join("\n").trim();
}

// Pull a JSON array out of a model reply. Two real shapes seen in practice
// (2026-07-27 live-testing): a chatty model wraps the array in prose despite
// instructions, AND — the actual bug found here — Ollama's `format: "json"`
// mode constrains output to valid JSON but NOT specifically an array, so for
// a single-delegate request the model happily returns one bare {...} object
// instead of a [{...}] array; the prompt asking for an array doesn't override
// that. Handles both: tries array-brackets first, falls back to a single
// object wrapped in an array.
function extractJsonArray(text) {
  if (!text) return null;
  const arrStart = text.indexOf("[");
  const arrEnd = text.lastIndexOf("]");
  if (arrStart >= 0 && arrEnd > arrStart) {
    try {
      const parsed = JSON.parse(text.slice(arrStart, arrEnd + 1));
      if (Array.isArray(parsed)) return parsed;
    } catch { /* fall through to object attempt below */ }
  }
  const objStart = text.indexOf("{");
  const objEnd = text.lastIndexOf("}");
  if (objStart >= 0 && objEnd > objStart) {
    try {
      const parsed = JSON.parse(text.slice(objStart, objEnd + 1));
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return [parsed];
    } catch { /* not valid JSON either way */ }
  }
  return null;
}

function buildPrompt(request, roster) {
  const rosterLines = roster.map((d) =>
    `- id "${d.id}" = ${d.name}${d.vip ? " (VIP)" : ""}, coach ${d.coachName || "?"}, currently: hotel "${d.hotelName || "none"}", room "${d.roomNumber || "none"}"`
  ).join("\n");
  return `You translate a staff member's plain-language room-assignment request into a JSON array of updates for a hotel/room tracker. Output ONLY a JSON array, no prose, no markdown fences.

Roster (use the id EXACTLY as given — never invent an id, never include a delegate not listed here):
${rosterLines}

Each item in your output array must be exactly: {"delegateId": "<id from the roster above>", "hotelName": "<string or null to leave unchanged>", "roomNumber": "<string or null to leave unchanged>"}
- Only include delegates the request actually applies to (e.g. "VIPs" → only VIP rows above; "everyone" → every row above; a named person → just that person, matched by name).
- If the request only sets a hotel (not specific rooms), set "roomNumber": null for every item — do NOT invent room numbers.
- If the request only sets room numbers for named people, set "hotelName": null for those items unless a hotel was also specified.
- Never output a delegateId that isn't in the roster above.

Staff request: "${String(request).slice(0, 400)}"

JSON array:`;
}

/** Re-checked server-side on BOTH endpoints — never trust a client-supplied
 *  delegateId list blindly. Mirrors RoomManagementTab's own "roomable"
 *  scope (coach-assigned delegates only) and the coach-captain Staff
 *  visibility restriction every other delegate-reading route already
 *  enforces (see getVisibleCoachIds' doc in db/dashboard.js). */
async function getRoomableRoster(tripUuid, account) {
  const visibleCoachIds = await getVisibleCoachIds(tripUuid, account);
  const delegates = await listDelegates(tripUuid);
  return delegates.filter((d) => d.coachId && (!visibleCoachIds || visibleCoachIds.has(d.coachId)));
}

router.post("/api/trips/:id/rooms/ai-suggest", requirePermission("manageDelegates"), wrap(async (req, res) => {
  const request = (req.body?.request || "").trim();
  if (!request) return res.status(400).json({ error: "REQUEST_REQUIRED", message: "Please describe what you want to change." });

  const tripUuid = await resolveTripUuid(req.params.id);
  const roster = await getRoomableRoster(tripUuid, req.account);
  if (roster.length === 0) return res.json({ suggestions: [] });

  const prompt = buildPrompt(request, roster);
  let raw = await tryOllama(prompt, { numPredict: 600 });
  let parsed = extractJsonArray(raw);
  if (!parsed) {
    raw = await callAnthropic(prompt, 800);
    parsed = extractJsonArray(raw);
  }
  if (!parsed) {
    return res.status(503).json({ error: "AI_NOT_CONFIGURED", message: "AI isn't available right now (no local Ollama and no ANTHROPIC_API_KEY configured), or it couldn't understand that request. Try phrasing it differently, or edit rows manually below." });
  }

  const byId = new Map(roster.map((d) => [d.id, d]));
  const suggestions = [];
  for (const item of parsed.slice(0, MAX_SUGGESTIONS)) {
    if (!item || typeof item !== "object") continue;
    const delegate = byId.get(item.delegateId);
    if (!delegate) continue; // not a real id on this roster — dropped, never trusted
    const hotelName = item.hotelName === null || item.hotelName === undefined ? undefined : String(item.hotelName).trim();
    const roomNumber = item.roomNumber === null || item.roomNumber === undefined ? undefined : String(item.roomNumber).trim();
    if (hotelName === undefined && roomNumber === undefined) continue; // nothing to actually change
    suggestions.push({
      delegateId: delegate.id,
      name: delegate.name,
      hotelName: hotelName !== undefined ? hotelName : delegate.hotelName || "",
      roomNumber: roomNumber !== undefined ? roomNumber : delegate.roomNumber || "",
    });
  }
  res.json({ suggestions });
}));

router.post("/api/trips/:id/rooms/ai-apply", requirePermission("manageDelegates"), wrap(async (req, res) => {
  const updates = Array.isArray(req.body?.updates) ? req.body.updates : [];
  if (!updates.length) return res.status(400).json({ error: "NO_UPDATES", message: "Nothing to apply." });

  const tripUuid = await resolveTripUuid(req.params.id);
  const roster = await getRoomableRoster(tripUuid, req.account);
  const validIds = new Set(roster.map((d) => d.id));

  const actor = actorOf(req);
  let applied = 0;
  for (const u of updates) {
    if (!u || !validIds.has(u.delegateId)) continue; // re-validated here too — never trust the client's list
    await updateDelegate(u.delegateId, {
      hotelName: (u.hotelName || "").trim(),
      roomNumber: (u.roomNumber || "").trim(),
    }, actor);
    applied++;
  }
  res.json({ applied });
}));

export default router;
